const sameOrigin=r=>r.headers.get('Origin')===new URL(r.url).origin;
async function content(env){if(!env.BUCKET)return {data:DEFAULTS,version:null};const o=await env.BUCKET.get('site/content.json');return {data:o?{...DEFAULTS,...await o.json()}:DEFAULTS,version:o?.etag??null};}
function validURL(v){return !v||(/^https:\/\//.test(v)&&!/[<>"']/.test(v))||/^\/(?:media|community-media)\/[a-f0-9-]+$/.test(v)}
function cleanContent(d){for(const k of ['title','tagline','intro','about','announcement','email','instagram','video','accent'])if(typeof d[k]!=='string'||d[k].length>10000)throw Error('Check your content fields.');if(!/^#[a-f0-9]{6}$/i.test(d.accent))throw Error('Choose a valid color.');if(!validURL(d.video)||!validURL(d.instagram))throw Error('Use an HTTPS link.');if(d.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))throw Error('Enter a valid contact email.');for(const k of ['events','products','gallery']){if(!Array.isArray(d[k])||d[k].length>200)throw Error('Too many items.');for(const x of d[k]){if(!x||typeof x.title!=='string'||!x.title.trim()||x.title.length>200)throw Error('Each item needs a title.');if(!validURL(x.image||'')||!validURL(x.link||''))throw Error('Use an HTTPS link for images and links.');if(k==='events'&&!/^\d{4}-\d{2}-\d{2}$/.test(x.date))throw Error('Choose an event date.');if(k==='products'&&(!Number.isFinite(Number(x.price))||Number(x.price)<0))throw Error('Enter a valid price.');}}return Object.fromEntries(Object.keys(DEFAULTS).map(k=>[k,d[k]]));}
