const HTML=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080a0c"><meta name="description" content="Finish The Race Motorsports. A shared passion for cars. A greater purpose in Christ."><title>Finish The Race Motorsports</title><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><div class="announcement" id="announcement">Built on faith. Brought together by motorsports.</div><header><a class="brand" href="#/" aria-label="Finish The Race home"><img src="/brand/wordmark.jpg" alt="Finish The Race Motorsports"></a><button id="menu" class="icon menu" aria-expanded="false" aria-label="Toggle navigation">☰</button><nav id="nav"><a href="#/">Home</a><a href="#/about">Our mission</a><a href="#/events">Events</a><a href="#/fellowship">Fellowship</a><a href="#/gallery">Gallery</a><a href="#/shop">Shop</a><a href="#/contact">Contact</a><a class="member-nav" href="#/account">Member account</a></nav><div class="utilities"><button class="icon" id="account" aria-label="Customer account">Account ↗</button><button class="icon" id="cart" aria-label="Open cart">Bag <span id="bagcount">0</span></button></div></header><main id="main" tabindex="-1"></main><footer><div class="footer-top"><img src="/brand/mark.jpg" alt="FTR Motorsports"><div><h3>Keep the faith.<br>Finish the race.</h3><p>A shared passion. A greater purpose.</p></div><div><a href="#/about">Our mission</a><a href="#/events">Upcoming events</a><a href="#/fellowship">Fellowship</a><a href="#/shop">FTR merchandise</a></div><div><a href="#/contact">Contact us</a><a href="#/privacy">Privacy policy</a><a href="#/admin">Manage website ↗</a></div></div><div class="footer-bottom"><span>© <span id="year"></span> Finish The Race Motorsports</span><span>2 Timothy 4:7</span><span class="preview">Website preview</span></div></footer><dialog id="dialog"><button class="close" aria-label="Close dialog">×</button><div id="dialogbody"></div></dialog><div class="toast" role="status" id="toast"></div></body></html>`;
