if(p==='/api/members/login'&&r.method==='POST'){if(typeof env.MEMBER_PASSWORD_PEPPER!=='string'||env.MEMBER_PASSWORD_PEPPER.length<32)return fail('Member password security is not configured.',503);const denied=await limit('login');if(denied)return denied;const d=await json();if(!emailOK(d.email)||typeof d.password!=='string'||d.password.length>256)return fail('Incorrect email or password.',401);const m=await env.DB.prepare('SELECT * FROM members WHERE email=?').bind(d.email.toLowerCase().trim()).first();const check=await passwordHash(d.password,m?.password_salt||'fixed-dummy-salt-for-timing',env);if(!m||!await equalPassword(check,m.password_hash))return fail('Incorrect email or password.',401);if(!m.verified)return fail('Verify your email before signing in. You can resend verification from the account page.',403);const token=rand();await env.DB.prepare('INSERT INTO member_sessions(token_hash,member_id,expires) VALUES(?,?,?)').bind(await hashToken(token),m.id,NOW()+604800000).run();return cookieResponse({member:publicMember(m)},memberCookie(token));}
