if(p==='/api/fellowship/submit'&&r.method==='POST'){const denied=await limit('forms');if(denied)return denied;const d=await json();if(d.website)return response({ok:true,message:'Submission received.'});if(!['testimony','prayer'].includes(d.type))return fail('Invalid post type.');if(d.type==='testimony'&&(!member||!member.verified))return fail('Verified member sign-in is required for testimonies.',401);if(d.audio||d.video||d.link)return fail('Voice, video, and links are reserved for admin Messages from FTR. Member posts support pictures and text only.');if(d.type==='prayer'&&d.image)return fail('Prayer requests are text only.');const image=str(d.image||'',200);if(image){if(!/^\/community-media\/[a-f0-9-]+$/.test(image))return fail('Upload your picture using the member form.');const o=await env.BUCKET?.get(image.slice(1));if(!o||o.customMetadata?.memberId!==member?.id)return fail('You can only attach your own uploaded picture.',403);}const title=str(d.title,160),body=str(d.body||'',5000);if(!title||(!image&&body.length<10))return fail('Add a title and a picture or at least 10 characters of text.');if(offensive(title+' '+body))return fail('This submission contains language we cannot accept. Please revise it.',422);if(hasPublicLink(title+' '+body))return fail('Community submissions must be plain text without links or HTML.');if(d.email&&!emailOK(d.email))return fail('Enter a valid email or leave it blank.');const pub=d.type==='testimony'||d.share_public===true;if(pub&&d.consent_public!==true)return fail('Confirm permission to share this publicly after review.');const name=d.anonymous===true?'Anonymous':str(d.type==='testimony'?member.display_name:(d.author||(member?.display_name)||'Anonymous'),80)||'Anonymous';if(offensive(name))return fail('Please revise the display name.',422);const status=pub&&!image?'published':'pending';const id=crypto.randomUUID(),now=new Date().toISOString();await env.DB.prepare("INSERT INTO fellowship_posts(id,type,member_id,author,email,title,body,image,visibility,consent_public,status,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(id,d.type,member?.id||null,name,d.email||member?.email||'',title,body,image,pub?'public':'private',pub?1:0,status,now,now).run();return response({ok:true,id,message:status==='published'?'Your post is now published.':pub?'Thank you. FTR will review your submission before it appears publicly.':'Your prayer request was sent privately to the FTR team.'},201);}
